    {
      "headline": "Món đầu tiên: Mì Quảng Bà Mua",
      "body": "Bữa sáng đúng kiểu: sợi nghệ, tôm thịt, bánh tráng giòn. Ngon quá là câu bạn sẽ nói.",
      "item_id": "0199a0f2-0000-7000-8000-00000000d001"
    },
    {
      "headline": "My Khe Beach chờ bạn",
      "body": "Biển xanh, cát mịn, nắng sớm. Đi chân trần một vòng rồi hẵng tính chuyện ăn gì tiếp.",
      "item_id": "0199a0f2-0000-7000-8000-00000000d002"
    },
    {
      "headline": "Rồng phun lửa",
      "body": "Tối đến, rồng sẽ phun lửa. Đứng gần cầu, nhớ giữ túi xách. Tôi ngồi trên cây cũng xem ké được.",
      "item_id": "0199a0f2-0000-7000-8000-00000000d004"
    },
    {
      "headline": "Lựa chọn nhẹ nhàng",
      "body": "Bỏ Ba Na Hills, bạn giữ lại 350.000 ₫ để ăn thêm vài món ngon.",
      "item_id": null
    }
  ],
